import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';

test('balanceDue returns the full total for unpaid invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const balance = balanceDue(invoice);
  assert(balance > 0);
});

test('balanceDue returns 0 for fully paid invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 114500, date: '2026-10-10' }],
  };

  const balance = balanceDue(invoice);
  assert.equal(balance, 0);
});

test('balanceDue accounts for partial payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 10000,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 50000, date: '2026-10-10' }],
  };

  const balance = balanceDue(invoice);
  assert(balance > 0);
  assert(balance < 121000);
});

test('recordPayment creates payments array if missing', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });

  assert.equal(result.ok, true);
  assert(Array.isArray(result.value.payments));
  assert.equal(result.value.payments.length, 1);
  assert.equal(result.value.payments[0].amount, 50000);
  assert.equal(result.value.payments[0].date, '2026-10-10');
});

test('recordPayment adds to existing payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 10000,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 60000, date: '2026-10-10' }],
  };

  const result = recordPayment(invoice, { amount: 61000, date: '2026-10-15' });

  assert.equal(result.ok, true);
  assert.equal(result.value.payments.length, 2);
});

test('recordPayment sets status to partially_paid when balance remains', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 10000,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });

  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'partially_paid');
});

test('recordPayment sets status to paid when invoice is fully paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const balance = 114500;
  const result = recordPayment(invoice, { amount: balance, date: '2026-10-10' });

  assert.equal(result.ok, true);
  assert.equal(result.value.status, 'paid');
});

test('recordPayment reports NOT_ISSUED for draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 1000, date: '2026-10-10' });

  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment reports NOT_ISSUED for paid invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 114500, date: '2026-10-10' }],
  };

  const result = recordPayment(invoice, { amount: 1000, date: '2026-10-15' });

  assert.deepEqual(result, { ok: false, error: 'NOT_ISSUED' });
});

test('recordPayment accepts issued status', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });

  assert.equal(result.ok, true);
});

test('recordPayment accepts partially_paid status', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
    payments: [{ amount: 50000, date: '2026-10-10' }],
  };

  const result = recordPayment(invoice, { amount: 30000, date: '2026-10-15' });

  assert.equal(result.ok, true);
});

test('recordPayment reports AMOUNT_INVALID for zero amount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 0, date: '2026-10-10' });

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports AMOUNT_INVALID for negative amount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: -1000, date: '2026-10-10' });

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports AMOUNT_INVALID for fractional amount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 1000.5, date: '2026-10-10' });

  assert.deepEqual(result, { ok: false, error: 'AMOUNT_INVALID' });
});

test('recordPayment reports DATE_INVALID for invalid date', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 1000, date: 'not-a-date' });

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('recordPayment reports OVERPAYMENT for amount exceeding balance', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 999999999, date: '2026-10-10' });

  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment does not mutate input invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  recordPayment(invoice, { amount: 50000, date: '2026-10-10' });

  assert.deepEqual(invoice, invoiceCopy);
});

test('recordPayment preserves invoice data', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 1);
});

