import test from 'node:test';
import assert from 'node:assert/strict';
import { recordPayment, balanceDue } from '../src/payments.js';

test('balanceDue returns the full total for unpaid invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const balance = balanceDue(invoice);
  assert(balance > 0);
});

test('balanceDue returns 0 for fully paid invoice', () => {
