  assert.deepEqual(result, { ok: false, error: 'OVERPAYMENT' });
});

test('recordPayment does not mutate input invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  recordPayment(invoice, { amount: 50000, date: '2026-10-10' });

  assert.deepEqual(invoice, invoiceCopy);
});

test('recordPayment preserves invoice data', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };

  const result = recordPayment(invoice, { amount: 50000, date: '2026-10-10' });

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 1);
});
